param(
  [ValidateSet('x86','x64')][string]$CompileArchitecture,
  [string]$SourceDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/dxvk-remix'),
  [string]$OutputDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/lazy-logging-test')
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$SourceDirectory = (Resolve-Path -LiteralPath $SourceDirectory).Path
New-Item -ItemType Directory -Force $OutputDirectory | Out-Null
$OutputDirectory = (Resolve-Path -LiteralPath $OutputDirectory).Path
if (!$CompileArchitecture) {
  foreach ($architecture in @('x86','x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileArchitecture $architecture -SourceDirectory $SourceDirectory -OutputDirectory $OutputDirectory
    if ($LASTEXITCODE -ne 0) { throw "Lazy logging tests failed: $architecture" }
  }
  exit 0
}
. (Join-Path $SourceDirectory 'bridge/build_common.ps1')
SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
foreach ($variant in @('current','eager-buffer','preinit-drop')) {
  $testDir = Join-Path $OutputDirectory "$variant-$CompileArchitecture"
  New-Item -ItemType Directory -Force $testDir | Out-Null
  $extractArgs = @("$PSScriptRoot/prepare_lazy_logging_test.py", $SourceDirectory, $testDir)
  if ($variant -ne 'current') { $extractArgs += @('--negative-control', $variant) }
  & python @extractArgs
  if ($LASTEXITCODE -ne 0) { throw "Lazy logging extraction failed: $variant" }
  Push-Location $testDir
  try {
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /O2 /MT "/I$testDir" "$repoRoot/tests/lazy_logging.cpp" /Fe:lazy-logging.exe
    if ($LASTEXITCODE -ne 0) { throw "Lazy logging compilation failed: $variant" }
    if ($variant -eq 'current') {
      foreach ($mode in @('startup-trace','startup-info','behavior')) {
        & ./lazy-logging.exe $mode
        if ($LASTEXITCODE -ne 0) { throw "Production lazy logging regression failed: $mode" }
      }
    } else {
      $mode = if ($variant -eq 'eager-buffer') { 'behavior' } else { 'startup-trace' }
      $reason = if ($variant -eq 'eager-buffer') { 'disabled buffer logging performed extra allocations' } else { 'pre-init messages were discarded instead of buffered' }
      & cmd.exe /d /c "lazy-logging.exe $mode > regression-output.txt 2>&1"
      $controlExit = $LASTEXITCODE
      $controlOutput = Get-Content -LiteralPath 'regression-output.txt' -Raw
      Write-Host $controlOutput
      if ($controlExit -ne 1 -or $controlOutput -notmatch [regex]::Escape($reason)) {
        throw "Lazy logging negative control failed for the wrong reason: $variant"
      }
    }
  } finally {
    Pop-Location
  }
}
